import { makeJavaBlitz } from './builders.mjs';

/**
 * 90 unique Java 1v1 Quick Blitz questions (10 per Easy/Med/Hard × 3m/5m/10m).
 * Uses public class Main + Scanner(System.in) cleanly compatible with Judge0, Wandbox, and javac.
 */
function javaSpec(id, difficulty, durationSecs, title, description, inputSetup, starterTodo, implBody, testCases) {
  const build = (body) =>
    `import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n${inputSetup}\n${body}\n    }\n}\n`;
  return makeJavaBlitz({
    id,
    title,
    difficulty,
    durationSecs,
    description,
    starterBody: build(starterTodo),
    solutionCode: build(implBody),
    testCases,
  });
}

const READ_INT_ARR = `        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextInt();`;
const READ_K_INT_ARR = `        int k = sc.nextInt(), n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextInt();`;

